INSERT INTO commerce_product_category_attribute
    (id, tenant_id, organization_id, category_id, attribute_id, attribute_role,
     source_category_id, is_required, is_searchable, is_filterable, is_comparable,
     sort_order, status)
SELECT 130000 + (ord - 1) * 4 + 1, 100001, 0, category_id, 1104, 'sales',
       NULL::bigint, TRUE, TRUE, TRUE, TRUE, 10, 'active'
FROM leaf
UNION ALL
SELECT 130000 + (ord - 1) * 4 + 2, 100001, 0, category_id, 110010, 'sales',
       NULL::bigint, TRUE, TRUE, TRUE, TRUE, 20, 'active'
FROM leaf
UNION ALL
SELECT 130000 + (ord - 1) * 4 + 3, 100001, 0, category_id,
       CASE profile
           WHEN 'tech' THEN 1108
           WHEN 'office' THEN 1108
           WHEN 'appliance' THEN 1108
           WHEN 'beauty' THEN 110011
           WHEN 'food' THEN 110011
           WHEN 'baby' THEN 110011
           ELSE 1107
       END,
       'parameter', NULL::bigint, FALSE, FALSE, TRUE, FALSE, 30, 'active'
FROM leaf
UNION ALL
SELECT 130000 + (ord - 1) * 4 + 4, 100001, 0, category_id, 1109, 'parameter',
       NULL::bigint, FALSE, FALSE, TRUE, FALSE, 40, 'active'
FROM leaf
WHERE profile = 'appliance'
ON CONFLICT (id) DO UPDATE SET
    category_id = EXCLUDED.category_id,
    attribute_id = EXCLUDED.attribute_id,
    attribute_role = EXCLUDED.attribute_role,
    is_required = EXCLUDED.is_required,
    is_searchable = EXCLUDED.is_searchable,
    is_filterable = EXCLUDED.is_filterable,
    is_comparable = EXCLUDED.is_comparable,
    sort_order = EXCLUDED.sort_order,
    status = EXCLUDED.status,
    updated_at = NOW();

