INSERT INTO commerce_product_spu
    (id, tenant_id, organization_id, spu_no, category_id, brand_id, name, title,
     product_type, status, sales_status, published_at)
SELECT 150000 + g,
       100001,
       0,
       'ind-' || g,
       l.category_id,
       220000 + ((g - 1) % 12),
       b.short || ' ' || chr(65 + ((g - 1) % 6)) || ((g % 90) + 10)::text || ' ' || l.noun,
       b.short || ' ' || chr(65 + ((g - 1) % 6)) || ((g % 90) + 10)::text || ' ' || l.noun || ' '
           || (CASE ((g - 1) % 4) WHEN 0 THEN '标准装' WHEN 1 THEN '家庭装' WHEN 2 THEN '礼盒装' ELSE '大容量装' END),
       'physical',
       CASE WHEN (g - 1) % 100 < 88 THEN 'active'
            WHEN (g - 1) % 100 < 93 THEN 'draft'
            WHEN (g - 1) % 100 < 97 THEN 'inactive'
            ELSE 'archived' END,
       CASE WHEN (g - 1) % 100 < 88 THEN 'active' ELSE 'inactive' END,
       CASE WHEN (g - 1) % 100 < 88 THEN NOW() ELSE NULL END
FROM generate_series(1, 1200) AS g
JOIN leaf l ON l.ord = ((g - 1) % 40) + 1
JOIN (VALUES
    (0, '星云'), (1, '极光'), (2, '流明'), (3, '简白'), (4, '云舒'), (5, '木言'),
    (6, '花间'), (7, '山野'), (8, '智联'), (9, '优学'), (10, '驰行'), (11, '悦然')
) AS b(bid, short) ON b.bid = (g - 1) % 12
ON CONFLICT (id) DO UPDATE SET
    spu_no = EXCLUDED.spu_no,
    category_id = EXCLUDED.category_id,
    brand_id = EXCLUDED.brand_id,
    name = EXCLUDED.name,
    title = EXCLUDED.title,
    product_type = EXCLUDED.product_type,
    status = EXCLUDED.status,
    sales_status = EXCLUDED.sales_status,
    published_at = EXCLUDED.published_at,
    updated_at = NOW();

