        (13, 100031, 3900, 99900), (14, 100032, 2900, 129900), (15, 100033, 1900, 59900), (16, 100034, 900, 29900),
        (17, 100041, 900, 19900), (18, 100042, 1500, 29900), (19, 100043, 900, 19900), (20, 100044, 1200, 39900),
        (21, 100051, 29900, 599900), (22, 100052, 5900, 99900), (23, 100053, 1900, 49900), (24, 100054, 3900, 99900),
        (25, 100061, 4900, 99900), (26, 100062, 9900, 299900), (27, 100063, 5900, 199900), (28, 100064, 19900, 499900),
        (29, 100071, 2900, 59900), (30, 100072, 1900, 29900), (31, 100073, 2900, 49900), (32, 100074, 1900, 59900),
        (33, 100081, 500, 19900), (34, 100082, 49900, 399900), (35, 100083, 19900, 299900), (36, 100084, 900, 9900),
        (37, 100091, 3900, 99900), (38, 100092, 900, 19900), (39, 100093, 1900, 49900), (40, 100094, 19900, 399900)
)
INSERT INTO commerce_product_sku
    (id, tenant_id, organization_id, spu_id, sku_no, variant_signature, name, title,
     currency_code, price_scale, list_price_minor, sale_price_minor,
     fulfillment_type, inventory_tracking, inventory_policy,
     status, sales_status, published_at)
SELECT 160000 + (g - 1) * 2 + k,
       100001,
       0,
       150000 + g,
       'ind-' || g || '-' || k,
       'color=' || (CASE ((g + k - 2) % 6) WHEN 0 THEN 'obsidian' WHEN 1 THEN 'moonwhite' WHEN 2 THEN 'starryblue'
                                           WHEN 3 THEN 'sakura' WHEN 4 THEN 'forest' ELSE 'titanium' END)
           || ';package_spec=' || (CASE ((g + k - 2) % 4) WHEN 0 THEN 'standard' WHEN 1 THEN 'family'
                                                          WHEN 2 THEN 'gift' ELSE 'large' END),
       sp.name || ' ' || (CASE ((g + k - 2) % 6) WHEN 0 THEN '曜石黑' WHEN 1 THEN '月光白' WHEN 2 THEN '星空蓝'
                                                  WHEN 3 THEN '樱花粉' WHEN 4 THEN '森林绿' ELSE '钛银灰' END),
       sp.title || ' ' || (CASE ((g + k - 2) % 4) WHEN 0 THEN '标准装' WHEN 1 THEN '家庭装' WHEN 2 THEN '礼盒装' ELSE '大容量装' END),
       'CNY',
       2,
       l.band_min + ((g::bigint * 137) % (l.band_max - l.band_min + 1)),
       (l.band_min + ((g::bigint * 137) % (l.band_max - l.band_min + 1)))
           - ((l.band_min + ((g::bigint * 137) % (l.band_max - l.band_min + 1))) * (5 + (g % 20)) / 100),
       'physical',
       'quantity',
       CASE WHEN g % 10 = 0 THEN 'backorder' ELSE 'deny' END,
       sp.status,
       sp.sales_status,
       sp.published_at
FROM commerce_product_spu sp
CROSS JOIN LATERAL (SELECT sp.id - 150000 AS g) AS gen
JOIN leaf l ON l.ord = ((g - 1) % 40) + 1
CROSS JOIN generate_series(1, 2) AS k
WHERE sp.id BETWEEN 150001 AND 151200
ON CONFLICT (id) DO UPDATE SET
    spu_id = EXCLUDED.spu_id,
    sku_no = EXCLUDED.sku_no,
    variant_signature = EXCLUDED.variant_signature,
    name = EXCLUDED.name,
    title = EXCLUDED.title,
    currency_code = EXCLUDED.currency_code,
    price_scale = EXCLUDED.price_scale,
    list_price_minor = EXCLUDED.list_price_minor,
    sale_price_minor = EXCLUDED.sale_price_minor,
    fulfillment_type = EXCLUDED.fulfillment_type,
    inventory_tracking = EXCLUDED.inventory_tracking,
    inventory_policy = EXCLUDED.inventory_policy,
    status = EXCLUDED.status,
    sales_status = EXCLUDED.sales_status,
    published_at = EXCLUDED.published_at,
    updated_at = NOW();

-- ---------------------------------------------------------------------------
-- SKU axes: colour and package specification per SKU.
-- ---------------------------------------------------------------------------
INSERT INTO commerce_product_sku_attribute
    (id, tenant_id, organization_id, sku_id, attribute_id, attribute_value_id, sort_order)
SELECT 170000 + (s.id - 160000) * 2 + ax.axis - 1,
       100001,
       0,
       s.id,
       ax.attribute_id,
       CASE ax.axis
           WHEN 1 THEN (CASE ((((s.id - 160000) / 2) + ((s.id - 160000) % 2)) % 6)
                            WHEN 0 THEN 1215 WHEN 1 THEN 1216 WHEN 2 THEN 1217
                            WHEN 3 THEN 1225 WHEN 4 THEN 1226 ELSE 1227 END)
           ELSE 1240 + ((((s.id - 160000) / 2) + ((s.id - 160000) % 2)) % 4)
       END,
       ax.sort_order
FROM commerce_product_sku s
JOIN (VALUES (1, 1104, 10), (2, 110010, 20)) AS ax(axis, attribute_id, sort_order) ON TRUE
WHERE s.id BETWEEN 160001 AND 162400
ON CONFLICT (id) DO UPDATE SET
    sku_id = EXCLUDED.sku_id,
    attribute_id = EXCLUDED.attribute_id,
    attribute_value_id = EXCLUDED.attribute_value_id,
    sort_order = EXCLUDED.sort_order,
    updated_at = NOW();

-- ---------------------------------------------------------------------------
-- SPU specifications (one parameter per product, by industry profile).
-- ---------------------------------------------------------------------------
WITH leaf(ord, category_id, profile) AS (
    VALUES
        (1, 100001, 'tech'), (2, 100002, 'tech'), (3, 100003, 'tech'), (4, 100004, 'tech'),
        (5, 100011, 'appliance'), (6, 100012, 'appliance'), (7, 100013, 'appliance'), (8, 100014, 'appliance'),
        (9, 100021, 'apparel'), (10, 100022, 'apparel'), (11, 100023, 'apparel'), (12, 100024, 'apparel'),
        (13, 100031, 'beauty'), (14, 100032, 'beauty'), (15, 100033, 'beauty'), (16, 100034, 'beauty'),
        (17, 100041, 'food'), (18, 100042, 'food'), (19, 100043, 'food'), (20, 100044, 'food'),
        (21, 100051, 'home'), (22, 100052, 'home'), (23, 100053, 'home'), (24, 100054, 'home'),
        (25, 100061, 'sports'), (26, 100062, 'sports'), (27, 100063, 'sports'), (28, 100064, 'sports'),
        (29, 100071, 'baby'), (30, 100072, 'baby'), (31, 100073, 'baby'), (32, 100074, 'baby'),
        (33, 100081, 'office'), (34, 100082, 'office'), (35, 100083, 'office'), (36, 100084, 'office'),
        (37, 100091, 'auto'), (38, 100092, 'auto'), (39, 100093, 'auto'), (40, 100094, 'auto')
)
INSERT INTO commerce_product_spu_attribute
    (id, uuid, tenant_id, organization_id, spu_id, attribute_id, attribute_value_id,
     raw_value, attribute_role, sort_order)
SELECT 180000 + g,
       gen_random_uuid(),
       100001,
       0,
       150000 + g,
       CASE profile
           WHEN 'tech' THEN 1108
           WHEN 'office' THEN 1108
           WHEN 'appliance' THEN 1109
           WHEN 'beauty' THEN 110011
           WHEN 'food' THEN 110011
           WHEN 'baby' THEN 110011
           ELSE 1107
       END,
       NULL,
       CASE profile
           WHEN 'tech' THEN (CASE g % 3 WHEN 0 THEN '12' ELSE '24' END)
           WHEN 'office' THEN (CASE g % 3 WHEN 0 THEN '12' ELSE '24' END)
           WHEN 'appliance' THEN ((500 + (g * 37) % 2000))::text
           WHEN 'beauty' THEN (CASE g % 3 WHEN 0 THEN '6' WHEN 1 THEN '12' ELSE '24' END)
           WHEN 'food' THEN (CASE g % 3 WHEN 0 THEN '6' WHEN 1 THEN '12' ELSE '24' END)
           WHEN 'baby' THEN (CASE g % 3 WHEN 0 THEN '6' WHEN 1 THEN '12' ELSE '24' END)
           ELSE (CASE g % 5 WHEN 0 THEN '铝合金' WHEN 1 THEN 'ABS' WHEN 2 THEN '纯棉' WHEN 3 THEN '真皮' ELSE '不锈钢' END)
       END,
       'parameter',
       10
FROM generate_series(1, 1200) AS g
JOIN leaf l ON l.ord = ((g - 1) % 40) + 1
ON CONFLICT (id) DO UPDATE SET
    spu_id = EXCLUDED.spu_id,
    attribute_id = EXCLUDED.attribute_id,
    attribute_value_id = EXCLUDED.attribute_value_id,
    raw_value = EXCLUDED.raw_value,
    attribute_role = EXCLUDED.attribute_role,
    sort_order = EXCLUDED.sort_order,
    updated_at = NOW();

-- ---------------------------------------------------------------------------
-- Media: one main image per SPU, plus a gallery image every fifth product.
-- ---------------------------------------------------------------------------
INSERT INTO commerce_product_media
    (id, uuid, tenant_id, organization_id, owner_type, owner_id, media_role,
     media_resource_id, resource_snapshot, alt_text, sort_order, status)
SELECT 240000 + (g - 1) * 2 + m,
       gen_random_uuid(),
       100001,
       0,
       'spu',
       150000 + g,
       CASE m WHEN 1 THEN 'main_image' ELSE 'gallery_image' END,
       900000 + (g - 1) * 2 + m,
       jsonb_build_object(
           'id', (900000 + (g - 1) * 2 + m)::text,
           'kind', 'image',
           'source', 'external_url',
           'url', 'https://picsum.photos/seed/industry-' || g || '-' || m || '/640/480',
           'fileName', 'industry-' || g || '-' || m || '.png',
           'mimeType', 'image/png'
       ),
       sp.name || CASE m WHEN 1 THEN ' 主图' ELSE ' 场景图' END,
       CASE m WHEN 1 THEN 0 ELSE 10 END,
       'active'
FROM generate_series(1, 1200) AS g
CROSS JOIN generate_series(1, 2) AS m
JOIN commerce_product_spu sp ON sp.id = 150000 + g
WHERE m = 1 OR g % 5 = 0
ON CONFLICT (id) DO UPDATE SET
    owner_type = EXCLUDED.owner_type,
    owner_id = EXCLUDED.owner_id,
    media_role = EXCLUDED.media_role,
    media_resource_id = EXCLUDED.media_resource_id,
    resource_snapshot = EXCLUDED.resource_snapshot,
    alt_text = EXCLUDED.alt_text,
    sort_order = EXCLUDED.sort_order,
    status = EXCLUDED.status,
    updated_at = NOW();

-- ---------------------------------------------------------------------------
-- Retail price-list overrides for every active generated SKU.
-- ---------------------------------------------------------------------------
INSERT INTO commerce_price_list_item
    (id, uuid, tenant_id, organization_id, price_list_id, sku_id, currency_code,
     price_scale, price_minor, min_quantity, status)
SELECT 210000 + ROW_NUMBER() OVER (ORDER BY s.id) - 1,
       gen_random_uuid(),
       100001,
       0,
       2100,
       s.id,
       'CNY',
       2,
       s.sale_price_minor,
       1,
       'active'
FROM commerce_product_sku s
WHERE s.id BETWEEN 160001 AND 162400
  AND s.status = 'active'
ON CONFLICT (id) DO UPDATE SET
    price_list_id = EXCLUDED.price_list_id,
    sku_id = EXCLUDED.sku_id,
    currency_code = EXCLUDED.currency_code,
    price_scale = EXCLUDED.price_scale,
    price_minor = EXCLUDED.price_minor,
    min_quantity = EXCLUDED.min_quantity,
    status = EXCLUDED.status,
    updated_at = NOW();
